import {EXPEDITIONS,POS} from './expedition-data.mjs';import {ARCHIVE_LIMITS,archiveUsage,archiveFrame} from './expedition-report-archive.mjs';import {archiveSource} from './expedition-report-archive-guild.mjs';
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const basis=e=>e.source==='history'?'历史源按收藏时规则重演后冻结':e.source==='pending'?'保存时查看的待领取战报':'已领取正式战报的当前快照';
const stock=s=>`药草 ${s.herb} / 符纸 ${s.rune} / 箭矢 ${s.arrow}`;
export function archiveReaderView(entry,report,index,stale=false){const e=archiveFrame(report,index),summary=entry.summary;return `<section class="guild-panel archive-reader" data-guild-pane="history" id="report-archive-reader"><p class=eyebrow>冻结快照 / 只读回看</p><h2>${esc(entry.title)} · 第${entry.id}次</h2><p>${esc(basis(entry))}；打开不会重新模拟，也不发放奖励。${stale?'本机来源已变化，请重新进入履历核对；当前仍显示打开时快照。':''}</p><p>${summary.won?'完成远征':'远征止步'} · 通过${summary.cleared}/${summary.roomCount}房 · ${summary.alive}/6人生还 · ${summary.rounds.join(' / ')}回合 · ${stock(summary.supplies)}</p><p>原来源记录：${entry.original.won?'通关':'止步'} / 通过${entry.original.cleared}房 · ${entry.original.gold}金币 / 每位出战者${entry.original.xp}经验，仅供核对。规则标识：${esc(entry.ruleset)}。</p><div class=archive-controls><label>房间<select id=archive-room>${report.rooms.map((r,i)=>`<option value="${i}" ${i===e.roomIndex?'selected':''}>${esc(r.name)}</option>`).join('')}</select></label><label>本房事件<select id=archive-event>${report.events.map((v,i)=>({v,i})).filter(({v})=>v.roomIndex===e.roomIndex).map(({v,i})=>`<option value="${i}" ${i===index?'selected':''}>${v.round}回合 · ${esc(v.phase)} · ${esc(v.text.slice(0,100))}</option>`).join('')}</select></label></div><label>完整事件 ${index+1} / ${report.events.length}<input id=archive-timeline type=range min=0 max="${report.events.length-1}" value="${index}"></label><div class=bar><button data-archive-step=first ${index===0?'disabled':''}>全程开头</button><button data-archive-step=prev ${index===0?'disabled':''}>上一事件</button><button data-archive-step=next ${index===report.events.length-1?'disabled':''}>下一事件</button><button data-archive-step=last ${index===report.events.length-1?'disabled':''}>全程结尾</button><button data-archive-export="${entry.id}">导出完整快照</button><button data-archive-use="${entry.id}">载入战术供下次调整</button></div><article class=archive-event aria-live=polite><p>第${e.round}回合 · ${esc(e.phase)} · 原事件${e.id}</p><h3>${esc(e.text)}</h3><p>${stock(e.supplies)}</p></article><div class=archive-units>${e.units.map(u=>`<article><h4>${esc(u.name)}${u.owner?' · 召唤物':''}</h4><p>${u.side==='party'?'我方':'敌方'} · ${POS[u.pos]} · ${u.bypassed?'已绕过，未交战':u.hp>0?'仍可行动':u.mechanism?'已拆除':'已倒下/消散'}<br>${u.mechanism?'耐久':'生命'} ${u.hp}/${u.maxHp} · 法力 ${u.mp}/${u.maxMp}</p><p>效果：${esc(u.effects.map(f=>f.name+(f.active===false?'（待生效）':'')).join('、')||'无')}</p></article>`).join('')}</div><details><summary>当前事件完整原始字段</summary><pre>${esc(JSON.stringify(e,null,2))}</pre></details><details><summary>冻结的出发方案与队员统计</summary><pre>${esc(JSON.stringify({config:report.config,perspective:report.perspective||null,stats:report.stats},null,2))}</pre></details><p>载入战术保留当前本人、伙伴职责、实际装备与培养；正式出征仍需核对当前公会资产，并分配新的正常种子。</p></section>`;}
export function archiveLibraryView(g,reader=null,stale=false){const entries=g.reportArchives||[],usage=archiveUsage(entries),entry=entries.find(e=>e.id===reader?.id&&e.snapshot.sha256===reader.sha256);return `<section class="guild-panel report-archives" data-guild-pane="history" id=report-archives><h2>关键战报收藏 · ${entries.length}/${ARCHIVE_LIMITS.slots}</h2><p>最近履历滚动保留20次。将查看中的正式/历史战报主动冻结后，可独立保留完整事件，随整档携带；不是当年的原始报告存储，也不是奖励凭据。</p><p>收藏容量已用 ${(100*usage.encodedChars/ARCHIVE_LIMITS.encodedChars).toFixed(1)}%；最多6份，按压缩后的实际大小计入总容量；新收藏无损保存完整事件与当时状态。浏览器存储仍可能受限，请定期导出整档。</p>${entries.map(e=>`<article data-archive-card="${e.id}"><h3>第${e.id}次 · ${esc(EXPEDITIONS[e.route].name)}</h3><p>${e.summary.won?'完成':'止步'} · ${e.summary.alive}/6人生还 · ${esc(basis(e))}</p><label>收藏名称<input id="archive-name-${e.id}" maxlength=40 value="${esc(e.title)}"></label><div class=bar><button data-archive-open="${e.id}">回看冻结快照</button><button data-archive-export="${e.id}">导出完整快照</button><button data-archive-use="${e.id}">载入战术</button><button data-archive-rename="${e.id}">保存名称</button><button data-archive-remove="${e.id}">移除此收藏</button></div></article>`).join('')||'<p>尚未收藏。在正式或最近履历的战报页，可保存当前完整快照。</p>'}</section>${entry?archiveReaderView(entry,reader.report,reader.index,stale):''}`;}
export function mountArchiveCapture({getGuild,getReport,getOrigin,onSave,onLibrary,tell}){const root=document.querySelector('#report-archive-controls'),drafts=new Map();let current=null,busy=false;
 function render(){const report=getReport();root.hidden=true;if(!report)return;try{const g=getGuild(),origin=getOrigin(),{record,source}=archiveSource(g,origin,report),saved=g.reportArchives?.find(e=>e.id===record.id);current=record.id;root.hidden=false;root.innerHTML=`<h2>保留关键战报</h2><p>${source==='history'?'保存此刻按当前规则重演的完整快照。':source==='pending'?'保存当前查看的待领取快照，奖励仍须正常领取。':'保存这份已领取正式战报的当前快照。'}打开收藏不重新模拟，普通履历滚出20条后仍可回看。</p>${saved?`<p>已收藏：${esc(saved.title)}</p>`:`<label>收藏名称<input id=archive-capture-name maxlength=40 value="${esc(drafts.get(current)||'第'+current+'次 · '+EXPEDITIONS[report.config.expedition].name)}"></label>`}<div class=bar>${saved?'':`<button data-archive-capture=true ${busy?'disabled':''}>${busy?'正在压缩并校验…':'冻结收藏这份战报'}</button>`}<button data-archive-library=true>查看我的收藏 →</button></div>`;}catch{current=null;root.innerHTML='';}}
 root.oninput=e=>{if(e.target.id==='archive-capture-name'&&current)drafts.set(current,e.target.value);};root.onclick=async e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.archiveLibrary){onLibrary();return;}if(!b.dataset.archiveCapture||busy)return;const report=getReport(),origin={...getOrigin()},name=root.querySelector('#archive-capture-name').value;busy=true;render();try{await onSave(report,origin,name);tell('完整战报快照已收藏；事件和当时方案已冻结，资产与收益保留。');}catch(error){tell('未能收藏：'+error.message);}finally{busy=false;render();}};
 return {render,hide:()=>{root.hidden=true;root.innerHTML='';}};
}
